//     __ _____ _____ _____\n//  __|  |   __|     |   | |  JSON for Modern C++\n// |  |  |__   |  |  | | | |  version 3.12.0\n// |_____|_____|_____|_|___|  https://github.com/nlohmann/json\n//\n// SPDX-FileCopyrightText: 2013-2025 Niels Lohmann <https://nlohmann.me>\n// SPDX-License-Identifier: MIT\n\n#pragma once\n\n#include <nlohmann/detail/input/lexer.hpp>\n#include <nlohmann/detail/input/input_adapters.hpp>\n#include <nlohmann/detail/value_t.hpp>\n\nNLOHMANN_JSON_NAMESPACE_BEGIN\nnamespace detail\n{\n\n/*!\n@brief parse state for resuming parsing\n\nThis class stores the state of the parser and lexer to allow resuming parsing\nfrom a previously saved state.\n*/\ntemplate<typename BasicJsonType>\nclass parse_state\n{\n    using lexer_t = lexer<BasicJsonType, input_adapter>;\n    using token_type = typename lexer_t::token_type;\n    using lexer_state_type = lexer_t::state_type;\n\npublic:\n    /// default constructor\n    parse_state() = default;\n\n    /// copy constructor\n    parse_state(const parse_state&) = default;\n\n    /// move constructor\n    parse_state(parse_state&&) = default;\n\n    /// copy assignment operator\n    parse_state& operator=(const parse_state&) = default;\n\n    /// move assignment operator\n    parse_state& operator=(parse_state&&) = default;\n\n    /// destructor\n    ~parse_state() = default;\n\n    /// lexer state\n    lexer_state_type lexer_state;\n\n    /// last token read by the parser\n    token_type last_token = token_type::uninitialized;\n\n    /// memory limit in bytes (0 means no limit)\n    std::size_t memory_limit = 0;\n\n    /// relative memory limit (0.0 means no limit, 1.0 means 100% of system memory)\n    double relative_memory_limit = 0.0;\n};\n\n}  // namespace detail\nNLOHMANN_JSON_NAMESPACE_END